package com.capacitix.repository; import com.capacitix.entity.LearningPathItem; import com.capacitix.entity.TrainingModule; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Repository; import java.util.List; import java.util.Optional; @Repository public interface TrainingModuleRepository extends JpaRepository<TrainingModule, Long> { /** * Find all active training modules. */ List<TrainingModule> findByActiveTrue(); /** * Find active modules for a particular skill. */ List<TrainingModule> findBySkillNameIgnoreCaseAndActiveTrue( String skillName ); /** * Find modules for a particular difficulty level. */ List<TrainingModule> findByDifficultyLevelAndActiveTrue( TrainingModule.DifficultyLevel difficultyLevel ); /** * Find modules by skill and difficulty. */ List<TrainingModule> findBySkillNameIgnoreCaseAndDifficultyLevelAndActiveTrue( String skillName, TrainingModule.DifficultyLevel difficultyLevel ); /** * Find a module by title. */ Optional<TrainingModule> findByTitleIgnoreCase( String title ); /** * Check whether a module with the given title exists. */ boolean existsByTitleIgnoreCase( String title ); /** * Find modules by module type. */ List<TrainingModule> findByModuleTypeAndActiveTrue( TrainingModule.ModuleType moduleType ); /** * Search active modules by skill name. */ List<TrainingModule> findBySkillNameContainingIgnoreCaseAndActiveTrue( String skillName ); /** * Find all modules belonging to a particular * learning path item. * * Modules are returned in creation order. */ List<TrainingModule> findByLearningPathItemOrderByCreatedAtAsc( LearningPathItem learningPathItem ); /** * Find active modules belonging to a particular * learning path item. */ List<TrainingModule> findByLearningPathItemAndActiveTrueOrderByCreatedAtAsc( LearningPathItem learningPathItem ); /** * Check whether a training module already exists * for a learning path item. */ boolean existsByLearningPathItem( LearningPathItem learningPathItem ); /** * Find all active personalized modules. */ List<TrainingModule> findByPersonalizedTrueAndActiveTrue(); }